package android.content.res;import java.io.*;
/** HOST ONLY staged public assets; no private profile imports. */
public final class AssetManager {final File root;public AssetManager(File r){root=r;}public InputStream open(String name)throws IOException{if(name.equals("project7_baiye_shop/catalog-v1.tsv"))return new FileInputStream(System.getProperty("p7.baiye.shop"));if(name.equals("project7_baiye/fragments-v1.tsv"))return new FileInputStream(System.getProperty("p7.baiye.fragments"));if(name.equals("project7_baiye/catalog-v1.tsv"))return new FileInputStream(System.getProperty("p7.baiye.catalog"));if(!name.matches("[a-zA-Z0-9_./-]+")||name.contains(".."))throw new IOException("public asset name");File f=new File(root,name);if(!f.getCanonicalFile().toPath().startsWith(root.getCanonicalFile().toPath()))throw new IOException("asset path");return new FileInputStream(f);}}
